window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[316]={"id":"316","numero":316,"titre":"Syndromes myélodysplasiques (SMD)","objectifs":[{"id":"316-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un syndrome myélodysplasique (SMD)","contenu":"<p>Les <span class=\"kw-def\">syndromes myélodysplasiques</span> (SMD) sont un groupe d'<strong>hémopathies clonales</strong> de la <span class=\"kw-def\">cellule souche hématopoïétique</span> médullaire, caractérisées par une anomalie de la <strong>production et de la maturation</strong> des cellules sanguines de la lignée <span class=\"kw-def\">myéloïde</span>. L'atteinte est à la fois :</p>\n      <ul>\n        <li><strong>Quantitative</strong> — une ou plusieurs <span class=\"kw-clinique\">cytopénies</span> périphériques (<span class=\"kw-clinique\">anémie</span>, <span class=\"kw-clinique\">thrombopénie</span>, <span class=\"kw-clinique\">neutropénie</span>).</li>\n        <li><strong>Qualitative</strong> — anomalies <span class=\"kw-def\">morphologiques et fonctionnelles</span> des cellules sanguines (dysmyélopoïèse).</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Physiopathologie</span></strong> — l'atteinte clonale repose sur des anomalies cytogénétiques / génétiques <span class=\"kw-etio\">acquises</span>, portant surtout sur les gènes de la <span class=\"kw-etio\">régulation épigénétique</span> et de l'<span class=\"kw-etio\">épissage de l'ARN</span>. Elle se traduit par :</p>\n      <ul>\n        <li>une <span class=\"kw-def\">apoptose excessive</span> des progéniteurs ;</li>\n        <li>une <span class=\"kw-def\">hématopoïèse inefficace</span> par avortement intramédullaire — d'où le contraste entre une moelle riche et des cytopénies périphériques.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Discriminant clé <span class=\"kw-bio\">vs</span> leucémie aiguë.</strong> Dans la <span class=\"kw-def\">leucémie aiguë</span>, les progéniteurs sont <span class=\"kw-alerte\">bloqués au stade de blaste</span>. Dans le SMD, ils <strong>évoluent</strong> en cellules immatures dysplasiques (non bloqués) — des blastes circulants peuvent exister mais restent <span class=\"kw-chiffre\">&lt; 5 %</span>.</div>\n      <p><strong>Profil évolutif</strong> — deux trajectoires : une forme <strong>prolongée et indolente</strong> (~<span class=\"kw-chiffre\">70 %</span>, aggravation progressive des cytopénies) et une forme <strong>agressive</strong> avec transformation en <span class=\"kw-alerte\">leucémie aiguë myéloïde</span> (~<span class=\"kw-chiffre\">30 %</span>). Détail dans l'objectif « profil évolutif ».</p>\n      <p><strong><span class=\"kw-def\">Épidémiologie</span></strong> — <span class=\"kw-def\">incidence</span> ~<span class=\"kw-chiffre\">4/100 000/an</span>, qui croît fortement avec l'âge (jusqu'à ~<span class=\"kw-chiffre\">70/100 000/an</span> entre 70 et <span class=\"kw-chiffre\">80 ans</span>). Maladie de l'adulte <span class=\"kw-chiffre\">&gt; 60 ans</span> (médiane au diagnostic <span class=\"kw-chiffre\">65-70 ans</span>), avec une légère prédominance masculine (~<span class=\"kw-chiffre\">60 %</span>).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 315 — Leucémie aiguë · 317 — Syndrome myéloprolifératif</em></p>","frequence":0},{"id":"316-2","rang":"B","rubrique":"Etiologie","titre":"Connaître les étiologies des SMD","contenu":"<p>Dans <strong>~<span class=\"kw-chiffre\">85 %</span> des cas</strong>, le SMD est <span class=\"kw-etio\">primitif</span> (idiopathique, spontané, sans cause identifiée). Les <span class=\"kw-etio\">SMD secondaires</span> représentent le reste et relèvent des étiologies suivantes :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Agents / situations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Chimiothérapies</span><br><em>SMD ~<span class=\"kw-chiffre\">10 ans</span> après l'exposition</em></td>\n            <td>\n              <strong>Agents alkylants :</strong> <span class=\"kw-ttt\">melphalan</span> ; <span class=\"kw-ttt\">chlorambucil</span> ; <span class=\"kw-ttt\">cyclophosphamide</span> ; <span class=\"kw-ttt\">cisplatine</span><br>\n              <strong>Analogues des purines :</strong> <span class=\"kw-ttt\">fludarabine</span> ; <span class=\"kw-ttt\">mercaptopurine</span> ; <span class=\"kw-ttt\">clofarabine</span><br>\n              <strong>Autres :</strong> conditionnements d'autogreffe ; plus exceptionnellement pipobroman, <span class=\"kw-ttt\">azathioprine</span><br>\n              <em>Anomalies cytogénétiques caractéristiques sur les chromosomes 5 ou 7, souvent complexes.</em>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Radiations &amp; toxiques</span></td>\n            <td>\n              <strong>Radiations ionisantes :</strong> <span class=\"kw-ttt\">radiothérapie</span><br>\n              <strong>Toxiques :</strong> <span class=\"kw-etio\">benzène</span> (rôle le mieux établi) ; <span class=\"kw-etio\">tabac</span> (très probable, via les hydrocarbures benzéniques)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Pathologies acquises</span></td>\n            <td>Syndrome myéloprolifératif ; aplasie médullaire ; hémoglobinurie paroxystique nocturne</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Pathologies constitutionnelles</span><br><em>très rares</em></td>\n            <td>Trisomie 21 ; anémie de Fanconi ; neurofibromatose ; neutropénie de Kostmann — responsables d'<strong>~1/3 des SMD de l'enfant</strong></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Les <span class=\"kw-ci\">inhibiteurs de la topo-isomérase II</span> (anthracyclines, VP16) ne donnent <strong>pas</strong> de SMD : ils induisent des <span class=\"kw-alerte\">LAM secondaires</span> d'emblée, non précédées de SMD. Le <span class=\"kw-ttt\">méthotrexate</span> n'induit habituellement pas de SMD.</div>\n      <div class=\"callout callout-info\"><strong>Maladie professionnelle.</strong> L'exposition professionnelle aux <span class=\"kw-etio\">radiations ionisantes</span>, au <span class=\"kw-etio\">benzène</span>, à certains toxiques industriels et aux essais nucléaires français (1960-1995) est reconnue comme maladie professionnelle.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 317 — Syndrome myéloprolifératif · 315 — Leucémie aiguë</em></p>","frequence":1},{"id":"316-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les anomalies de l’hémogramme","contenu":"<p>Le diagnostic est le plus souvent <strong>fortuit</strong>, sur un <span class=\"kw-bio\">hémogramme</span> systématique. Quand il est symptomatique, les signes traduisent les <span class=\"kw-clinique\">cytopénies</span> :</p>\n      <ul>\n        <li><strong>Syndrome anémique</strong> — l'<span class=\"kw-clinique\">anémie</span> est présente dans ~<span class=\"kw-chiffre\">80 %</span> des cas, d'installation progressive chez le sujet âgé (<span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-clinique\">pâleur</span>, <span class=\"kw-clinique\">dyspnée d'effort</span>).</li>\n        <li><strong>Syndrome <span class=\"kw-etio\">hémorragique</span></strong> — rarement révélateur, lié à la <span class=\"kw-clinique\">thrombopénie</span> ± thrombopathie.</li>\n        <li><strong>État <span class=\"kw-etio\">infectieux</span></strong> — lié à la <span class=\"kw-clinique\">neutropénie</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège : pas de syndrome <span class=\"kw-etio\">tumoral</span>.</strong> L'examen clinique est pauvre — <span class=\"kw-alerte\">pas d'adénomégalie, pas d'hépatosplénomégalie</span> (pas d'<span class=\"kw-ttt\">infiltration</span> blastique des organes). Exception : les formes frontières SMD/SMP, notamment la <span class=\"kw-def\">LMMC</span>, où une <span class=\"kw-clinique\">splénomégalie</span> est possible.</div>\n      <p><strong>Anomalies quantitatives</strong> — une ou plusieurs lignées touchées :</p>\n      <table >\n        <thead><tr><th>Lignée</th><th>Anomalie typique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Globules rouges</strong></td><td><span class=\"kw-bio\">Anémie normo- ou macrocytaire, arégénérative, normochrome</span> — quasi-constante (~<span class=\"kw-chiffre\">90 %</span>), de profondeur variable (<span class=\"kw-chiffre\">50 %</span> ont une Hb <span class=\"kw-chiffre\">&lt; 100 g/L</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Plaquettes</span></strong></td><td><span class=\"kw-bio\">Thrombopénie</span> modérée fréquente mais <strong>inconstante</strong>, rarement <span class=\"kw-chiffre\">&lt; 50 G/L</span> ; <span class=\"kw-bio\">thrombocytose</span> possible (jusqu'à <span class=\"kw-chiffre\">1000 G/L</span>) dans le syndrome 5q-</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Leucocytes</span></strong></td><td><span class=\"kw-bio\">Leuconeutropénie</span> inconstante (~<span class=\"kw-chiffre\">50 %</span> des cas, peut être normale) ; <span class=\"kw-bio\">monocytes &gt; 1 G/L</span> → évoque une <span class=\"kw-def\">LMMC</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Anomalies qualitatives au frottis</strong> — la <span class=\"kw-def\">dysmyélopoïèse</span> est visible sur le sang :</p>\n      <ul>\n        <li><strong>PNN</strong> — <span class=\"kw-bio\">hyposegmentés</span> (aspect <span class=\"kw-def\">pseudo-Pelger</span>), dégranulés.</li>\n        <li><strong>Globules rouges</strong> — <span class=\"kw-bio\">anisocytose</span> (tailles différentes), <span class=\"kw-bio\">poïkilocytose</span> (formes différentes).</li>\n        <li><strong><span class=\"kw-bio\">Plaquettes</span></strong> — géantes et hypogranuleuses.</li>\n        <li><strong>Blastes</strong> circulants en petit nombre (<span class=\"kw-chiffre\">&lt; 5 %</span>) dans ~<span class=\"kw-chiffre\">25 %</span> des cas.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Discriminant frottis.</strong> Deux aspects à ne pas confondre : <span class=\"kw-bio\">PNN hypersegmentés</span> → <span class=\"kw-etio\">carence en vitamine B12</span> ; <span class=\"kw-bio\">PNN dégranulés, peu segmentés (pseudo-Pelger)</span> → SMD.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 212 — <span class=\"kw-bio\">Hémogramme</span> · 213 — Anémie · 315 — Leucémie aiguë</em></p>","frequence":2},{"id":"316-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les anomalies du myélogramme","contenu":"<p>Le <span class=\"kw-bio\">myélogramme</span> (<span class=\"kw-ttt\">ponction</span> médullaire) est l'examen <strong>indispensable au diagnostic</strong> de SMD. Il associe trois analyses :</p>\n      <table >\n        <thead><tr><th>Analyse</th><th>Résultats dans le SMD</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Examen cyto-morphologique</strong></td>\n            <td>\n              <strong>Cellularité :</strong> moelle <span class=\"kw-bio\">riche</span> (normale ou augmentée) — contraste avec les cytopénies périphériques<br>\n              <strong>Dysmyélopoïèse</strong> (anomalie qualitative caractéristique) : dysérythropoïèse (anomalies nucléaires, cytoplasmes mal hémoglobinisés) ; dysgranulopoïèse (PNN mal segmentés, <span class=\"kw-def\">pseudo-Pelger</span>) ; dysmégacaryopoïèse (mégacaryocytes de petite taille / petit noyau)<br>\n              <strong>Blastes :</strong> excès <span class=\"kw-chiffre\">5-19 %</span> (toujours <span class=\"kw-chiffre\">&lt; 20 %</span>) dans ~<span class=\"kw-chiffre\">1/4</span> des cas\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen cytochimique</strong></td>\n            <td>\n              <strong>Coloration de Perls :</strong> visualise le fer dans les érythroblastes sous forme de <span class=\"kw-def\">sidéroblastes</span><br>\n              <strong>Sidéroblastes en couronne</strong> <span class=\"kw-chiffre\">&gt; 15 %</span> → caractérise le SMD avec sidéroblastes en couronne (fer dans les mitochondries collées au noyau)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen cytogénétique</strong><br><em>(caryotype médullaire)</em></td>\n            <td>\n              <strong>Indication :</strong> souvent indispensable au diagnostic, <strong>toujours indispensable au <span class=\"kw-def\">pronostic</span></strong><br>\n              <strong>Caractéristiques :</strong> anomalies <span class=\"kw-etio\">acquises</span> ; caryotype anormal dans ~<span class=\"kw-chiffre\">50 %</span> des SMD primitifs et ~<span class=\"kw-chiffre\">80 %</span> des SMD secondaires<br>\n              <strong>Type :</strong> surtout des délétions — del(5q), monosomie 7, trisomie 8 ; translocations équilibrées rares (contrairement aux leucémies aiguës)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Borne diagnostique à connaître.</strong> <span class=\"kw-alerte\">≥ 20 % de blastes</span> dans le sang ou la moelle = <span class=\"kw-def\">leucémie aiguë</span>, et non un SMD. Le SMD plafonne à <span class=\"kw-chiffre\">19 %</span> de blastes médullaires.</div>\n      <div class=\"callout callout-info\"><strong>Pour info — <span class=\"kw-def\">critères diagnostiques</span> OMS</strong> (hors collège). Diagnostic de SMD si <span class=\"kw-bio\">cytopénie(s)</span> chronique(s) persistante(s) <span class=\"kw-chiffre\">&gt; 6 mois</span> <strong>ET</strong> au moins un critère parmi : <span class=\"kw-bio\">dysplasie &gt; 10 %</span> d'une lignée myéloïde ; excès de blastes médullaires <span class=\"kw-chiffre\">5-19 %</span> ; caryotype anormal évocateur.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 315 — Leucémie aiguë</em></p>","frequence":5},{"id":"316-5","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les autres éléments du bilan biologique permettant d’évoquer un diagnostic différentiel","contenu":"<p>Au-delà du myélogramme (qui pose le <span class=\"kw-def\">diagnostic positif</span>), un bilan complémentaire sert à <strong>éliminer les diagnostics différentiels</strong> et à préparer la prise en charge.</p>\n      <p><strong>Bilan <span class=\"kw-ttt\">biologique</span> systématique</strong> — éliminer une autre cause d'<span class=\"kw-bio\">anémie normo- ou macrocytaire arégénérative</span> ou une carence associée :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Créatininémie</span> ;</li>\n        <li><span class=\"kw-bio\">Bilan hépatique</span> ;</li>\n        <li><span class=\"kw-bio\">Bilan thyroïdien</span> (<span class=\"kw-bio\">TSH</span>) ;</li>\n        <li><span class=\"kw-bio\">Vitamine B9</span> et <span class=\"kw-bio\">vitamine B12</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>BOM — non indispensable au diagnostic</strong> (contrairement au myélogramme). La <span class=\"kw-bio\">biopsie ostéo-médullaire</span> n'est réalisée que dans deux situations : moelle pauvre au myélogramme (~<span class=\"kw-chiffre\">15 %</span> des cas) ou suspicion de <span class=\"kw-def\">myélofibrose</span>. Bilan d'hémostase ± temps d'occlusion plaquettaire avant le geste.</div>\n      <p><strong><span class=\"kw-ci\">Bilan pré-thérapeutique</span></strong> (souvent réalisé en même temps) :</p>\n      <ul>\n        <li><span class=\"kw-bio\">EPO sérique</span> — un taux bas (<span class=\"kw-chiffre\">&lt; 500 UI/L</span>) prédit une réponse à l'<span class=\"kw-ttt\">EPO recombinante</span> ;</li>\n        <li><span class=\"kw-bio\">Ferritine</span> plasmatique — souvent élevée (hématopoïèse inefficace + transfusions).</li>\n      </ul>\n      <p><strong>Diagnostics différentiels</strong> et examen qui les évoque :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Diagnostic différentiel</span></th><th>Examen orientant</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Aplasie médullaire</span></td><td>Moelle pauvre ; <span class=\"kw-bio\">BOM</span></td></tr>\n          <tr><td><span class=\"kw-def\">Anémie carentielle</span></td><td>Dosage <span class=\"kw-bio\">B9 / B12</span></td></tr>\n          <tr><td><span class=\"kw-def\">Infiltration médullaire</span> (hémopathie maligne, métastase)</td><td><span class=\"kw-bio\">Myélogramme</span> et/ou <span class=\"kw-bio\">BOM</span></td></tr>\n          <tr><td><span class=\"kw-def\">Leucémie aiguë</span></td><td><span class=\"kw-bio\">Myélogramme</span> — blastes <span class=\"kw-chiffre\">&gt; 19 %</span></td></tr>\n          <tr><td><span class=\"kw-def\">Myélofibrose</span></td><td>Moelle pauvre au myélogramme ; <span class=\"kw-bio\">BOM</span></td></tr>\n          <tr><td>Autre cause d'<span class=\"kw-def\">anémie centrale</span></td><td><span class=\"kw-bio\">Bilan thyroïdien</span>, etc.</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 315 — Leucémie aiguë</em></p>","frequence":1,"liens":[{"href":"http://radiopaedia.org","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/myelodysplastic-syndrome","label":"Radiopaedia : Myelodysplastic syndrome"}]},{"id":"316-6","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître le profil évolutif des SMD","contenu":"<p>Le SMD évolue selon <strong>deux trajectoires</strong> dont la part conditionne le <span class=\"kw-def\">pronostic</span> :</p>\n      <table >\n        <thead><tr><th>Profil</th><th>Fréquence</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Prolongé et indolent</strong></td><td>~<span class=\"kw-chiffre\">70 %</span></td><td>Aggravation progressive des <span class=\"kw-clinique\">cytopénies</span> / <span class=\"kw-def\">insuffisance médullaire</span> ; surtout chez le sujet âgé</td></tr>\n          <tr><td><strong>Agressif</strong></td><td>~<span class=\"kw-chiffre\">30 %</span></td><td>Transformation en <span class=\"kw-alerte\">leucémie aiguë myéloïde</span> par de nouveaux événements génétiques et épigénétiques (hyperméthylation de l'ADN)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Survie</strong> — de quelques <strong>mois</strong> à quelques <strong>années</strong>. Causes de décès :</p>\n      <ul>\n        <li>~<span class=\"kw-chiffre\">50 %</span> des patients (très âgés) décèdent d'une <strong>autre maladie</strong> — surtout dans les SMD de faible risque ;</li>\n        <li><span class=\"kw-def\">Insuffisance médullaire</span> progressive (~<span class=\"kw-chiffre\">70 %</span>) ;</li>\n        <li>Transformation en <span class=\"kw-alerte\">LAM</span> (~<span class=\"kw-chiffre\">30 %</span>) ;</li>\n        <li>Complications transfusionnelles : risque <span class=\"kw-etio\">viral</span> (minime), <span class=\"kw-alerte\">hémochromatose secondaire</span> (surcharge ferrique hépatique ou cardiaque).</li>\n      </ul>\n      <p><strong>Stratification du risque</strong> — distinction pronostique majeure qui oriente l'objectif thérapeutique :</p>\n      <table >\n        <thead><tr><th></th><th>SMD faible risque</th><th>SMD haut risque</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Évolution</span> en LAM</td><td>Risque faible</td><td>Risque élevé</td></tr>\n          <tr><td>Survie</td><td>Prolongée (plusieurs années)</td><td>Brève (~<span class=\"kw-chiffre\">12 mois</span>)</td></tr>\n          <tr><td>Objectif thérapeutique</td><td>Améliorer la qualité de vie en traitant les cytopénies (surtout l'<span class=\"kw-clinique\">anémie</span>)</td><td>Retarder l'<span class=\"kw-clinique\">évolution</span> de la maladie et améliorer la survie</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Pour info — <span class=\"kw-def\">score</span> IPSS</strong> (passé rang C). Le score <span class=\"kw-def\">IPSS</span> classe les SMD en <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> g</span>roupes (risque très faible, faible, intermédiaire, élevé, très élevé) selon le nombre de cytopénies, le pourcentage de blastes médullaires et la cytogénétique. Autres facteurs de mauvais <span class=\"kw-def\">pronostic</span> : dépendance transfusionnelle, surcharge en fer, myélofibrose associée, mutations <span class=\"kw-etio\">ASXL1</span> / <span class=\"kw-etio\">TP53</span>. À retenir au rang B : l'<span class=\"kw-ttt\">allogreffe de cellules souches hématopoïétiques</span> est la seule thérapeutique potentiellement curative (réservée aux patients &lt;<span class=\"kw-chiffre\"> 70 ans</span> avec donneur HLA identique).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 315 — Leucémie aiguë</em></p>","frequence":2}],"astuces":[],"strategie":{"principes":"<p>La stratégie dépend entièrement de la <span class=\"kw-def\">stratification du risque</span> (faible <span class=\"kw-bio\">vs</span> haut risque). L'<span class=\"kw-ttt\">allogreffe de cellules souches hématopoïétiques</span> est la <strong>seule thérapeutique potentiellement curative</strong>.</p><p><strong>SMD de faible risque <span class=\"q\">— lutter contre les cytopénies</span></strong></p><p>Objectif = améliorer la <strong>qualité de vie</strong> en traitant les <span class=\"kw-clinique\">cytopénies</span> (surtout l'<span class=\"kw-clinique\">anémie</span>)</p><ul><li><span class=\"kw-ttt\">EPO</span> à fortes doses (ou <span class=\"kw-ttt\">darbépoïétine</span>) — surtout si <span class=\"kw-bio\">EPO sérique</span> <span class=\"kw-chiffre\">&lt; 500 UI/L</span></li><li><span class=\"kw-ttt\">Lénalidomide</span> : corrige l'<span class=\"kw-clinique\">anémie</span> du <span class=\"kw-def\">syndrome 5q-</span> dans <span class=\"kw-chiffre\">2/3</span> des cas</li><li><span class=\"kw-ttt\">Transfusions itératives de CGR phénotypés</span> si échec (objectif <span class=\"kw-chiffre\">Hb &gt; 10-11 g/dL</span>)</li></ul><p><strong>SMD de haut risque <span class=\"q\">— améliorer la survie</span></strong></p><p>Objectif = <strong>retarder l'<span class=\"kw-clinique\">évolution</span></strong> de la maladie et améliorer la survie</p><ul><li><span class=\"kw-ttt\">Agents hypométhylants</span> : <span class=\"kw-ttt\">azacytidine</span> (traitement de référence)</li><li><span class=\"kw-ttt\">Chimiothérapie</span> (<span class=\"kw-ttt\">anthracycline</span> + <span class=\"kw-ttt\">cytosine arabinoside</span>) — réservée aux patients jeunes, surtout à caryotype normal</li></ul><p><strong>Allogreffe de CSH <span class=\"q\">— rang B</span></strong></p><ul><li><span class=\"kw-ttt\">Allogreffe de cellules souches hématopoïétiques</span> = <strong>seule thérapeutique potentiellement curative</strong></li><li>Limitée aux patients <span class=\"kw-chiffre\">&lt; 70 ans</span> avec <span class=\"kw-bio\">donneur HLA identique</span> (~<span class=\"kw-chiffre\">10-15 %</span> des SMD)</li><li>Conditionnement <span class=\"kw-ttt\">atténué</span> chez le sujet âgé (moins <span class=\"kw-etio\">toxique</span> que le conditionnement myéloablatif)</li></ul>","suivi":"<p><strong>Hémogramme régulier :</strong> dépister l'aggravation des <span class=\"kw-clinique\">cytopénies</span> (<span class=\"kw-def\">insuffisance médullaire</span>, ~<span class=\"kw-chiffre\">70 %</span>) et la <span class=\"kw-alerte\">transformation en LAM</span> (~<span class=\"kw-chiffre\">30 %</span>).<br><strong>Surcharge martiale :</strong> surveiller la <span class=\"kw-bio\">ferritine</span> chez le patient transfusé — risque d'<span class=\"kw-alerte\">hémochromatose secondaire</span> (surcharge ferrique hépatique ou cardiaque).<br><strong>Réponse au traitement :</strong> rémission complète/partielle, amélioration hématologique (correction des <span class=\"kw-clinique\">cytopénies</span>), qualité de vie.<br><strong><span class=\"kw-def\">Pronostic</span> :</strong> <span class=\"kw-def\">score</span> <span class=\"kw-def\">IPSS</span> (<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> g</span>roupes de risque : nombre de cytopénies, % de blastes médullaires, cytogénétique).</p>"},"liensGlobaux":[{"href":"http://radiopaedia.org","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/myelodysplastic-syndrome","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Cytopénie(s) : bilan d'élimination puis myélogramme — Anémie normo/macrocytaire arégénérative ± thrombopénie ± neutropénie","detail":"<h4>CAT — démarche diagnostique devant une ou plusieurs cytopénies — Bilan d'élimination → myélogramme → stratification du risque</h4>","branches":[{"to":"t-extra","label":"Cause non médullaire retrouvée (carence, IRC, dysthyroïdie...)","color":"green"},{"to":"q-myelo","label":"Bilan biologique d'élimination négatif","color":"amber"}]},{"id":"t-extra","kind":"terminal","label":"Cytopénie d'origine non médullaire","color":"green","detail":"<h4>Bilan d'élimination</h4><ul><li><span class=\"kw-bio\">Vitamine B9</span> et <span class=\"kw-bio\">B12</span> → <span class=\"kw-etio\">anémie carentielle</span></li><li><span class=\"kw-bio\">Créatininémie</span> → <span class=\"kw-etio\">insuffisance rénale chronique</span></li><li><span class=\"kw-bio\">TSH</span> → <span class=\"kw-etio\">dysthyroïdie</span> ; <span class=\"kw-bio\">bilan hépatique</span> → <span class=\"kw-etio\">hépatopathie</span></li></ul><h4>Conduite</h4><ul><li>Corriger la cause et recontrôler l'<span class=\"kw-bio\">hémogramme</span> ; le <span class=\"kw-bio\">myélogramme</span> n'est pas nécessaire si la cause explique la/les cytopénie(s).</li></ul><h4>Renvoi</h4><ul><li>Item 213 (anémie) · Item 212 (hémogramme)</li></ul>"},{"id":"q-myelo","kind":"decision","label":"Myélogramme : richesse médullaire et dysmyélopoïèse ? — Examen indispensable au diagnostic de SMD","branches":[{"to":"t-pauvre","label":"Moelle pauvre (~15 % des cas)","color":"blue"},{"to":"q-blastes","label":"Moelle riche + dysmyélopoïèse","color":"amber"}]},{"id":"t-pauvre","kind":"terminal","label":"Moelle pauvre → BOM","color":"blue","detail":"<h4>Indication BOM</h4><ul><li>La <span class=\"kw-bio\">biopsie ostéo-médullaire</span> n'est faite que si la moelle est pauvre au myélogramme ou si l'on suspecte une <span class=\"kw-def\">myélofibrose</span> (non indispensable au diagnostic de SMD, contrairement au myélogramme).</li></ul><h4>Diagnostics à évoquer</h4><ul><li><span class=\"kw-etio\">Aplasie médullaire</span></li><li><span class=\"kw-etio\">Myélofibrose</span></li><li><span class=\"kw-etio\">Infiltration médullaire</span> (hémopathie maligne, métastase de tumeur solide)</li></ul><h4>Précaution</h4><ul><li>Bilan d'<span class=\"kw-bio\">hémostase</span> ± temps d'occlusion plaquettaire avant le geste (<span class=\"kw-clinique\">thrombopathie</span> fréquente).</li></ul>"},{"id":"q-blastes","kind":"decision","label":"Pourcentage de blastes (sang ou moelle) ? — Borne diagnostique majeure à 20 %","branches":[{"to":"t-la","label":"≥ 20 %","color":"red"},{"to":"q-risque","label":"< 20 % — critères de SMD réunis","color":"amber"}]},{"id":"t-la","kind":"terminal","label":"Leucémie aiguë (pas un SMD)","color":"red","detail":"<h4>Borne diagnostique</h4><ul><li><span class=\"kw-alerte\">≥ 20 % de blastes</span> dans le sang ou la moelle = <span class=\"kw-def\">leucémie aiguë</span>, et non un SMD (qui plafonne à <span class=\"kw-chiffre\">19 %</span> de blastes médullaires).</li></ul><h4>Physiopath</h4><ul><li>Progéniteurs <span class=\"kw-alerte\">bloqués au stade de blaste</span> (≠ SMD, où ils évoluent en cellules immatures dysplasiques).</li></ul><h4>Renvoi</h4><ul><li>Item 315 (leucémie aiguë)</li></ul>"},{"id":"q-risque","kind":"decision","label":"SMD confirmé : stratification pronostique ? — Caryotype + % de blastes + nombre de cytopénies (score IPSS)","branches":[{"to":"t-faible","label":"Faible risque","color":"green"},{"to":"t-haut","label":"Haut risque","color":"red"}]},{"id":"t-faible","kind":"terminal","label":"SMD de faible risque","color":"amber","detail":"<h4>Profil</h4><ul><li>Risque faible de transformation en <span class=\"kw-alerte\">LAM</span> ; survie <span class=\"kw-chiffre\">prolongée</span> (plusieurs années).</li></ul><h4>Objectif</h4><ul><li>Améliorer la <strong>qualité de vie</strong> en traitant les <span class=\"kw-clinique\">cytopénies</span> (surtout l'<span class=\"kw-clinique\">anémie</span>).</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">EPO</span> ± <span class=\"kw-ttt\">darbépoïétine</span> (si <span class=\"kw-bio\">EPO sérique</span> <span class=\"kw-chiffre\">&lt; 500 UI/L</span>)</li><li><span class=\"kw-ttt\">Lénalidomide</span> dans le <span class=\"kw-def\">syndrome 5q-</span></li><li><span class=\"kw-ttt\">Transfusions de CGR phénotypés</span> si échec (objectif <span class=\"kw-chiffre\">Hb &gt; 10-11 g/dL</span>)</li></ul>"},{"id":"t-haut","kind":"terminal","label":"SMD de haut risque","color":"red","detail":"<h4>Profil</h4><ul><li>Risque élevé de <span class=\"kw-alerte\">transformation en LAM</span> ; survie brève (~<span class=\"kw-chiffre\">12 mois</span>).</li></ul><h4>Objectif</h4><ul><li>Retarder l'<span class=\"kw-clinique\">évolution</span> de la maladie et améliorer la survie.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Azacytidine</span> (agent hypométhylant de référence)</li><li><span class=\"kw-ttt\">Chimiothérapie</span> (<span class=\"kw-ttt\">anthracycline</span> + <span class=\"kw-ttt\">cytosine arabinoside</span>) chez le patient jeune</li><li><span class=\"kw-ttt\">Allogreffe de CSH</span> (rang B) = seule curative, <span class=\"kw-chiffre\">&lt; 70 ans</span> avec <span class=\"kw-bio\">donneur HLA identique</span></li></ul>"}]},"cards":[{"i":"1341e02587f5","n":316,"o":"316-1","u":"Définition","t":"Connaître la définition d’un syndrome myélodysplasique (SMD)","q":"Comment se manifestent les anomalies des cellules sanguines observées dans les syndromes myélodysplasiques (SMD) ?","a":"<ul><li><strong>Quantitativement</strong> : par une ou plusieurs cytopénies périphériques (<strong>anémie, thrombopénie, neutropénie</strong>).</li><li><strong>Qualitativement</strong> : par des anomalies morphologiques et fonctionnelles des cellules sanguines (<strong>dysmyélopoïèse</strong>).</li></ul>"},{"i":"4387ee00f1c1","n":316,"o":"316-1","u":"Définition","t":"Connaître la définition d’un syndrome myélodysplasique (SMD)","q":"Quelle est l'épidémiologie des syndromes myélodysplasiques (SMD) ?","a":"<ul><li>L'incidence est d'environ <strong>4/100 000/an</strong>, augmentant fortement avec l'âge (jusqu'à 70/100 000/an entre 70 et 80 ans).</li><li>C'est une maladie de l'adulte de <strong>plus de 60 ans</strong> (âge médian au diagnostic 65-70 ans).</li><li>Il existe une légère prédominance masculine (~ 60 %).</li></ul>"},{"i":"6412accd7680","n":316,"o":"316-1","u":"Définition","t":"Connaître la définition d’un syndrome myélodysplasique (SMD)","q":"Comment différencier un syndrome myélodysplasique (SMD) d'une leucémie aiguë (LA) sur le plan de la maturation des cellules ?","a":"<p>Dans le <strong>SMD</strong>, les progéniteurs évoluent en cellules immatures dysplasiques (<strong>non bloqués</strong>), avec des blastes circulants généralement inférieurs à <strong>5 %</strong>. Dans la <strong>leucémie aiguë</strong>, les progéniteurs sont <strong>bloqués au stade de blaste</strong>.</p>"},{"i":"d995820540fc","n":316,"o":"316-1","u":"Définition","t":"Connaître la définition d’un syndrome myélodysplasique (SMD)","q":"Quelle est la physiopathologie principale des syndromes myélodysplasiques (SMD) et ses conséquences ?","a":"<p>La physiopathologie repose sur des <strong>anomalies cytogénétiques/génétiques acquises</strong> (souvent sur les gènes de la régulation épigénétique et de l'épissage de l'ARN), entraînant :</p><ul><li>Une <strong>apoptose excessive des progéniteurs</strong>.</li><li>Une <strong>hématopoïèse inefficace</strong> par avortement intramédullaire, expliquant le contraste entre une moelle riche et des cytopénies périphériques.</li></ul>"},{"i":"fff8e508aeed","n":316,"o":"316-1","u":"Définition","t":"Connaître la définition d’un syndrome myélodysplasique (SMD)","q":"Quelle est la définition des syndromes myélodysplasiques (SMD) ?","a":"<p>Les syndromes myélodysplasiques (SMD) sont un groupe d'<strong>hémopathies clonales</strong> de la cellule souche hématopoïétique médullaire, caractérisées par une anomalie de la production et de la maturation des cellules sanguines de la lignée myéloïde.</p>"},{"i":"033ee6db06ee","n":316,"o":"316-3","u":"Diagnostic positif","t":"Connaître les anomalies de l’hémogramme","q":"Quelles sont les anomalies quantitatives possibles concernant les plaquettes et les leucocytes dans les syndromes myélodysplasiques (SMD) ?","a":"<ul><li><strong>Plaquettes</strong> : une <strong>thrombopénie modérée</strong> est fréquente mais inconstante, rarement &lt; 50 G/L. Une <strong>thrombocytose</strong> (jusqu'à 1000 G/L) est possible, notamment dans le cadre du <strong>syndrome 5q-</strong>.</li><li><strong>Leucocytes</strong> : une <strong>leuconeutropénie</strong> est inconstante (~50% des cas). Une <strong>monocytose</strong> (&gt; 1 G/L) doit faire évoquer une <strong>leucémie myélomonocytaire chronique (LMMC)</strong>.</li></ul>"},{"i":"6ed314e91df6","n":316,"o":"316-3","u":"Diagnostic positif","t":"Connaître les anomalies de l’hémogramme","q":"Quelles sont les anomalies qualitatives spécifiques des différentes lignées sanguines visibles sur le frottis sanguin périphérique dans les syndromes myélodysplasiques (SMD) ?","a":"<ul><li><strong>Polynucléaires neutrophiles (PNN)</strong> : ils sont <strong>hyposegmentés</strong> (aspect <strong>pseudo-Pelger</strong>) et <strong>dégranulés</strong>.</li><li><strong>Globules rouges</strong> : on observe une <strong>anisocytose</strong> (tailles différentes) et une <strong>poïkilocytose</strong> (formes différentes).</li><li><strong>Plaquettes</strong> : elles peuvent être <strong>géantes</strong> et <strong>hypogranuleuses</strong>.</li><li>Des <strong>blastes circulants</strong> sont présents en petit nombre (&lt; 5%) dans environ 25% des cas.</li></ul>"},{"i":"a4420105a6fb","n":316,"o":"316-3","u":"Diagnostic positif","t":"Connaître les anomalies de l’hémogramme","q":"Quelle est l'anomalie quantitative la plus fréquente observable sur l'hémogramme dans les syndromes myélodysplasiques (SMD) et ses caractéristiques ?","a":"<p>L'anomalie quantitative la plus fréquente est l'<strong>anémie</strong> (quasi-constante, ~90% des cas). Elle est typiquement <strong>normo- ou macrocytaire</strong>, <strong>arégénérative</strong> et <strong>normochrome</strong>. Environ 50% des patients ont une hémoglobine &lt; 100 g/L.</p>"},{"i":"5ff52fd39a56","n":316,"o":"316-5","u":"Examens complémentaires","t":"Connaître les autres éléments du bilan biologique permettant d’évoquer un diagnostic différentiel","q":"Quels sont les principaux diagnostics différentiels des syndromes myélodysplasiques et quel examen permet de les évoquer ?","a":"<ul><li><strong>Aplasie médullaire</strong> : évoquée par une moelle pauvre au myélogramme et la BOM.</li><li><strong>Anémie carentielle</strong> : évoquée par le dosage des vitamines <strong>B9 et B12</strong>.</li><li><strong>Infiltration médullaire</strong> (hémopathie maligne, métastase) : évoquée par le myélogramme et/ou la BOM.</li><li><strong>Leucémie aiguë</strong> : évoquée par un myélogramme montrant des <strong>blastes > 19%</strong>.</li><li><strong>Myélofibrose</strong> : évoquée par une moelle pauvre au myélogramme et la BOM.</li><li><strong>Autre cause d'anémie centrale</strong> (par exemple, hypothyroïdie) : évoquée par le bilan thyroïdien.</li></ul>"},{"i":"679b834b7418","n":316,"o":"316-5","u":"Examens complémentaires","t":"Connaître les autres éléments du bilan biologique permettant d’évoquer un diagnostic différentiel","q":"Dans quel contexte doit-on réaliser une biopsie ostéo-médullaire (BOM) chez un patient suspect de syndrome myélodysplasique ?","a":"<p>La biopsie ostéo-médullaire n'est pas systématique pour le diagnostic de SMD. Elle est indiquée dans deux situations spécifiques :</p><ul><li>En cas de <strong>moelle pauvre au myélogramme</strong> (environ 15% des cas).</li><li>En cas de <strong>suspicion de myélofibrose</strong>.</li></ul>"},{"i":"d650654cbbd9","n":316,"o":"316-5","u":"Examens complémentaires","t":"Connaître les autres éléments du bilan biologique permettant d’évoquer un diagnostic différentiel","q":"Quel bilan biologique doit être réalisé chez un patient suspect de syndrome myélodysplasique (SMD) pour éliminer un diagnostic différentiel d'anémie arégénérative, en dehors de la ponction de moelle ?","a":"<p>Un bilan biologique systématique doit être réalisé, incluant :</p><ul><li><strong>Créatininémie</strong></li><li><strong>Bilan hépatique</strong></li><li><strong>Bilan thyroïdien (TSH)</strong></li><li><strong>Vitamine B9 et vitamine B12</strong></li></ul>"}]};